local BehaviorTreeBuilder     = import("Frame.AI.BT.BehaviorTreeBuilder")
local TaskStatus              = import("Frame.AI.BT.TaskStatus")
local AbortTypes              = import("Frame.AI.BT.Composites.AbortTypes")

local cs_coroutine            = require "XLua.cs_coroutine"
------------ import ------------

------------ define ------------

------------ define ------------

local Locate = {
    Home = 1,
    InTransit = 2,
    Mine = 3,
    Saloon = 4,
    Bank = 5,
}

local State = {
    MAX_FATIGUE     = 10,
    MAX_GOLD        = 5,
    MAX_THIRST      = 5,

    fatigue         = 0,
    thirst          = 0,
    gold            = 0,
    goldInBank      = 0,
    currentLocation = 0,
}

---@class AiComponent
local AiComponent = Class("AiComponent")

function AiComponent:__init()
    self._tree = nil
    self._state = State
    self._distanceToNextLocation = 10
end

function AiComponent:__delete()

end

function AiComponent:Start()
    local builder = BehaviorTreeBuilder.New(self)
    
    builder:Selector(AbortTypes.Self)
    
    builder:ConditionalDecoratorR(function(context)
        return context._state.fatigue >= State.MAX_FATIGUE
    end, false)
    builder:Sequence(AbortTypes.LowerPriority)
        :LogAction("-- 累了,准备回家")
        :Action(function(context)
            return context:GoToLocation(Locate.Home)
        end)
        :LogAction("-- 准备上床")
        :Action(function(context)
            return context:Sleep()
        end)    
        :EndComposite()


    builder:ConditionalDecoratorR(function(context)
        return context._state.thirst >= State.MAX_THIRST
    end, false)
    builder:Sequence(AbortTypes.LowerPriority)
           :LogAction("-- 渴了,准备喝水")
           :Action(function(context)
                return context:GoToLocation(Locate.Saloon)
            end)
           :LogAction("-- 开始喝水")
           :Action(function(context)
                return context:Drink()
            end)
           :EndComposite()
    
    
    self._tree = builder:Build()

    cs_coroutine.start(function()
        while(true) do
            self._tree:Tick() 
            CoYield(0.1)
            --cs_coroutine.yield_return()
        end
    end)
end

function AiComponent:GoToLocation(location)
    printInfo("前往目的地: %s. 距离: %s", location, self._distanceToNextLocation)

    if location ~= self._state.currentLocation then
        self._distanceToNextLocation = self._distanceToNextLocation - 1
        if self._distanceToNextLocation == 0 then
            self._state.fatigue = self._state.fatigue + 1
            self._state.currentLocation = location
            self._distanceToNextLocation = math.random(2, 8)
            return TaskStatus.Success
        end
        return TaskStatus.Running
    end
    
    return TaskStatus.Success
end

function AiComponent:Sleep()
    local fatigue = self._state.fatigue
    printInfo("开始睡觉, 当前疲惫值: %s", fatigue)
    if fatigue == 0 then
        return TaskStatus.Success
    end

    self._state.fatigue = fatigue - 1
    
    return TaskStatus.Running
end

function AiComponent:Drink()
    local thirst = self._state.thirst
    printInfo("开始喝水, 口渴程度:: %s", thirst)
    if thirst == 0 then
        return TaskStatus.Success
    end

    self._state.thirst = thirst - 1
    
    return TaskStatus.Running
end

return AiComponent
 